In this section, for any given monotone test function $f(\cdot)$, we provide an information-theoretic lower bound on the number of tests required by \emph{any} non-adaptive group testing algorithm that is allowed to make an error with probability at most $\varepsilon$. 

Let us first introduce some notation which will be used in the proof. We use a binary vector $\boldsymbol{{X}}\in \{0,1\}^n$ to represent the set ${\cal N}$, where $1$s indicate which items are defective.



To estimate $\boldsymbol{{X}}$, we perform $T$ suitable-designed tests, in which each test must be designed prior to observing any outcomes. Let $\boldsymbol{{Z}}=({Z}_1,\dots,{Z}_T)$ be a length $T$ vector, where ${Z}_i$ denotes the number of defectives in the $i$-th test.
The test outcomes are represented by a binary vector $\boldsymbol{{Y}}=({Y}_1,\dots,{Y}_T)\in\{0,1\}^T$, where ${Y}_i=1$ indicates the outcome of the $i$-th test is positive. We emphasize that ${Z}_i$ is independent of $({Y}_1,\dots, {Y}_{i-1},{Y}_{i+1},\dots,{Y}_{T})$. Given the tests and their outcomes, let $\boldsymbol{{\hat{X}}}$ be an estimate of $\boldsymbol{{X}}$.







 By standard information-theoretic definitions, we have
\begin{align} {H}(\boldsymbol{{X}}) &= {H}(\boldsymbol{{X}}|\boldsymbol{{Y}}) + {I}(\boldsymbol{{X}};\boldsymbol{{Y}})\notag\\
                           &={H}(\boldsymbol{{X}}|\boldsymbol{{Y}},\boldsymbol{{\hat{X}}}) + {I}(\boldsymbol{{X}};\boldsymbol{{Y}})\notag\\
                           &\leq {H}(\boldsymbol{{X}}|\boldsymbol{{\hat{X}}}) + {I}(\boldsymbol{{X}};\boldsymbol{{Y}})
\end{align}
where the second line follows since $\boldsymbol{{\hat{X}}}$ is a function of $\boldsymbol{{Y}}$; the thrid line follows from the fact that conditioning reduces entropy.
Since the defective set ${\cal D}$ is uniformly distributed over all length $n$ vector of Hamming weight $d$, we have
\begin{equation} {H}(\boldsymbol{{X}}) = \log \binom{n}{d}.
\end{equation}
By Fano's inequality,
\begin{equation} {H}(\boldsymbol{{X}} | \boldsymbol{{\hat{X}}}) \le 1 + \varepsilon \log\binom{n}{d}.
\end{equation}












Let ${Y}^{i-1}:=({Y}_1,\dots,{Y}_{i-1})$ and ${Z}^{i-1}:=({Z}_1,\dots,{Z}_{i-1})$.\footnote{For $i=1$, we follow the convention that ${Y}^{i-1}={Z}^{i-1}=\emptyset$.} Similar to channel coding (see for example \cite[Sec. 7.3]{yeung08}), it can be easily verified that \begin{align*}
(\boldsymbol{{X}},{Z}^{i-1}, {Y}^{i-1}) - {Z}_i - {Y}_i
\end{align*}
which implies
\begin{align} (\boldsymbol{{X}}, {Y}^{i-1}) - {Z}_i - {Y}_i.
\end{align}
Following a standard set of inequalities we have
\begin{align}
I(\boldsymbol{{X}};\boldsymbol{{Y}})&=\sum\limits_{i=1}^{T} \left[{H}({Y}_i | {Y}^{i-1}) - {H}({Y}_i |\boldsymbol{{X}},{Y}^{i-1})\right] \notag\\
                                  &\leq \sum\limits_{i=1}^{T} \left[{H}({Y}_i  ) - {H}({Y}_i | \boldsymbol{{X}},{Y}^{i-1})\right]  \notag\\
                                  &\leq\sum\limits_{i=1}^{T} \left[{H}({Y}_i  ) - {H}({Y}_i | \boldsymbol{{X}},{Y}^{i-1},{Z}_i)\right] \notag\\
                                  &= \sum\limits_{i=1}^{T} \left[{H}({Y}_i  ) - {H}({Y}_i | {Z}_i)\right] \end{align}
where the first line follows from chain rule; the second and third lines follow since conditioning reduces entropy;

the last line follows from \eqref{eq:markov:y_i:z_i}.






















Let ${\chi}_i$ denote the pool-size of the $i$-th test and $\Pr({Z}_i={a})$ denote the probability that ${Z}_i={a}$. We have
\begin{align}
    \Pr({Z}_i={a}) &= \frac{\binom{d}{{a}}\binom{n-d}{{\chi}_i-{a}}}{\binom{n}{{\chi}_i}}.
\end{align}
For simplicity, we define
\begin{equation}
\begin{aligned} {\mu}({\chi}_i) &\coloneqq \sum\limits_{{a}=0}^{d} \Pr({Z}_i={a}) f({a}), \\
    {\sigma^{2}}({\chi}_i) &\coloneqq \sum\limits_{{a}=0}^{d} \Pr({Z}_i={a}) \left(f({a})-{\mu}({\chi}_i)\right)^2,
\end{aligned}
\end{equation}
where ${\mu}({\chi}_i)$ and ${\sigma^{2}}({\chi}_i)$ denote the mean and variance of $\Pr({Y}_i=1 | {Z}_i)$.
It turns out we are able to bound the bracketed term $[\cdot]$ in \eqref{eq:cv:mi_3} as follows:
\begin{lemma} \begin{equation} {H}({Y}_i) - {H}({Y}_i | {Z}_i) \leq \frac{{\sigma^{2}}({\chi}_i) \log e}{{\mu}({\chi}_i)(1-{\mu}({\chi}_i))}
\end{equation}
\end{lemma}
\begin{IEEEproof}
See Appendix \ref{app:lem_cv}.
\end{IEEEproof}
Now substituting \eqref{eq:bound:y-y|z} into \eqref{eq:cv:mi_3}, we see that
\begin{align}
     {I}(\boldsymbol{{X}};\boldsymbol{{Y}}) 

    &\leq \sum\limits_{i=1}^{T} \frac{{\sigma^{2}}({\chi}_i)\log e}{{\mu}({\chi}_i)(1-{\mu}({\chi}_i))} \notag\\

    &\leq T \times \frac{{\sigma^{2}}({\chi}^*) \log e}{{\mu}({\chi}^*)(1-{\mu}({\chi}^*))}, \end{align}
where the second line follows by defining
\begin{align} {\chi}^*:=\mathrm{argmax}_{{\chi}\in \{1,\dots,n-1\}} \frac{{\sigma^{2}}({\chi})}{{\mu}({\chi})(1-{\mu}({\chi}))}.
\end{align}
The reason for restricting ${\chi}\in \{1,\dots,n-1\}$ is that ${\sigma^{2}}(0)={\sigma^{2}}(n)=0$.


Finally, combining \eqref{eq:cv:etp}, \eqref{eq:cv:H(x)}, \eqref{eq:cv:H(x|xh)} and \eqref{eq:cv:maxH_3}
gives us the desired result
\begin{equation} T \geq \frac{{\mu}({\chi}^*)\left(1-{\mu}({\chi}^*)\right)}{{\sigma^{2}}({\chi}^*) \log e} \left( (1-\varepsilon)\log\binom{n}{d} - 1 \right).
\end{equation}
This along with the definition of ${h(f)}$ in \eqref{eq:def:concen:para} completes the proof of Theorem \ref{thm:converse}.

