\end{equation}
which completes the proof.

We expand ${P(-,{q})}, {P(+,{q})},{Q(-,{q})}$ and ${P(+,{q})}$ using elementary combinatorial and algebraic identities. 
Regarding ${P(-,{q})}$, we have that 
\begin{align} {P(-,{q})} &= \sum\limits_{j=0}^{d} \binom{d}{j} {q}^j (1-{q})^{d-j} f(j) \notag\\ 
  &= (1-{q})^d f(0)+ \sum\limits_{j=1}^{d-1} \binom{d}{j} {q}^j (1-{q})^{d-j} f(j) +{q}^d f(d) \notag\\ 
 &=(1-{q})^d f(0)+ \sum\limits_{j=1}^{d-1} \left( \binom{d-1}{j} + \binom{d-1}{j-1} \right) {q}^j (1-{q})^{d-j} f(j)  +{q}^d f(d) \notag\\ 
&= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-j} f(j) + \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^j (1-{q})^{d-j} f(j).
\end{align}
Regarding ${P(+,{q})}$, by relabelling, we have that
\begin{align}
{P(+,{q})} &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(j+1) \\ 
&= \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^{j-1} (1-{q})^{d-j} f(j). \end{align}
From \eqref{eq:convert_p+_1} and \eqref{eq:convert_p+_2}, we can rewrite ${P(+,{q})}$ as 
\begin{align} {P(+,{q})} &= (1-{q}) \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(j+1) + {q} \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^{j-1} (1-{q})^{d-j} f(j) \notag\\
&= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-j} f(j+1) + \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^j (1-{q})^{d-j} f(j).
\end{align}
Combining \eqref{eq:convert_p-} and \eqref{eq:convert_p+}, we can write ${\Delta({q})}$ as
\begin{equation} \begin{aligned}
{\Delta({q})} &= {P(+,{q})} - {P(-,{q})} \\ 
&= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-j} (f(j+1) - f(j)).
\end{aligned}
\end{equation}
Under the assumption that $f(\cdot)$ is monotonically increasing and $f(0) < f(d)$, we conclude that 
\begin{align} {\Delta({q})} > 0 \; \text {  or equivalently  }\;   {P(+,{q})} >  {P(-,{q})}.
\end{align}
Similarly, regarding ${Q(-,{q})}$, we have
\begin{align*}
    {Q(-,{q})} &= \sum\limits_{j=0}^{d} \binom{d}{j} {q}^j (1-{q})^{d-j} f(j) \\ 
    &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-j} f(j) + \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^j (1-{q})^{d-j} f(j).
\end{align*}
And regarding ${Q(+,{q})}$, we have
\begin{align*}
    {Q(+,{q})} &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(j) \\ 
    &= \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^{j-1} (1-{q})^{d-j} f(j-1) \\ 
    &= (1-{q}) \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(j) + {q} \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^{j-1} (1-{q})^{d-j} f(j-1) \\
    &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-j} f(j) + \sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^j (1-{q})^{d-j} f(j-1).
\end{align*}
It then follows that 
\begin{align} {\nabla({q})} &={Q(-,{q})}-{Q(+,{q})} \\
    & =\sum\limits_{j=1}^{d} \binom{d-1}{j-1} {q}^j (1-{q})^{d-j} (f(j)-f(j-1)) \notag \\ 
    &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^{j+1} (1-{q})^{d-j-1} (f(j+1)-f(j)) \notag\\ 
    &= \frac{{q}}{1-{q}} {\Delta({q})},

\end{align}
where the last equality follows from \eqref{eq:convert_delta}. This together with \eqref{eq:P+>=P-} implies that 
\begin{align} {\nabla({q})} > 0 \; \text {  or equivalently  }\;  {Q(-,{q})} >  {Q(+,{q})}.
\end{align}
Using the monotonicity of $f(\cdot)$, we see that
\begin{align}
{P(+,{q})} &\le  \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(d)=f(d) \\ 
{Q(+,{q})} &\ge \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}^j (1-{q})^{d-1-j} f(0)=f(0) \end{align}
Combining \eqref{eq:P+>=P-}, \eqref{eq:Q->=Q+}, \eqref{eq:P+<f(d)} and \eqref{eq:Q+<f(d)}, along with the definitions of ${P(-,{q})}$ in \eqref{eq:def:p-p+} and ${Q(-,{q})}$ in \eqref{eq:def:p-pp+p}, we obtain
\begin{align} f(d)\ge  {P(+,{q})} > {P(-,{q})} = {Q(-,{q})} > {Q(+,{q})}  \ge f(0).
\end{align} 
Recalling the definition
\begin{align}
