                 &\geq \min\{{P(+,{q})}-{P(-,{q})},{P(+,{q})}-{P(-,{q})}\} \notag\\
                 &= {\Delta({q})}, \end{align}
and 
\begin{align} {P_{\min}({q})} & \geq \min\{{Q(-,{q})},1-{Q(+,{q})}\} \notag\\
              &\geq\min\{{Q(-,{q})}-{Q(+,{q})},{Q(-,{q})}-{Q(+,{q})}\} \notag\\
