    &\leq \exp \left( - \left( \frac{ \mathbb{E}({{m}_{i}})-{m}}{ \mathbb{E}({{m}_{i}})} \right)^2 \, \frac{ \mathbb{E}({{m}_{i}})}{2} \right) \\
    &= \exp \left( - \frac{ \mathbb{E}({{m}_{i}})}{2} + {m} - \frac{{m}^2}{2 \mathbb{E}({{m}_{i}})} \right) \\
    &\leq \exp \left( -\frac{ \mathbb{E}({{m}_{i}})}{2} + {m} \right) \\
    &\leq \exp \left( -\ln \left( \frac{2n}{\varepsilon} \right) \right)
    = \frac{\varepsilon}{2n},
    \end{aligned} 
