Below, the boundary points are handled separately. 

\begin{proposition} \begin{enumerate}
  \item  By choosing ${q}_0 = \frac {1} {d+1}$, which implicitly requires $f(1) - f(0)  > 0$,\footnote{ If $f(1) - f(0) =0 $ or $f(d) - f(d-1) =0$, we can  choose ${q}_0$ as in Proposition \ref{prop:existence}.} ${\hat{\Gamma}} ({q}_0)$ in \eqref{eq:def:fTp} satisfies 

\begin{equation} {\hat{\Gamma}} ({q}_0) \le \frac{266.45}{(f(1) - f(0))^2} d \log \left( \frac{2n}{\varepsilon} \right).
\end{equation}
\item  By choosing ${q}_0 =\frac {d} {d+1}$, which implicitly requires $f(d) - f(d-1) > 0$,$^{\ref{fn:boundary:cases}}$ ${\hat{\Gamma}} ({q}_0)$ in \eqref{eq:def:fTp} satisfies  

\begin{equation} {\hat{\Gamma}} ({q}_0) \leq \frac{266.45}{(f(d) - f(d-1))^2} d \log \left( \frac{2n}{\varepsilon} \right).
\end{equation}
\end{enumerate}

\end{proposition}




\begin{IEEEproof}
We prove the first part of the lemma directly.
Upon choosing ${q}_0 = \frac {1} {d+1}$, we have from \eqref{eq:convert_delta} that 
\begin{align*}
    {\Delta}({q}_0) &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}_0^j (1-{q}_0)^{d-j} (f(j+1) - f(j)) \\ 
    &\ge {q}_0^0 (1-{q}_0)^{d}  (f(1) - f(0)) \\
    &\ge \frac{f(1) - f(0)}{e}, 
\end{align*}
where the last inequality follows from the fact that $\left(1-\frac{1}{d+1}\right)^d$ is decreasing in $d$ and $\lim_{d\to \infty}\left(1-\frac{1}{d+1}\right)^d=\frac 1 e$.
Then, plugging this into \eqref{eq:def:fTp}, we obtain
\begin{align*}
    {\hat{\Gamma}} ({q}_0) = \frac{36.06(1-{q}_0)}{{q}_0 ({\Delta}({q}_0))^2} \log \left( \frac{2n}{\varepsilon} \right) \le \frac{266.45}{(f(1) - f(0))^2} d \log \left( \frac{2n}{\varepsilon} \right) ,
\end{align*}
which yields \eqref{eq:existence_margin_z} as desired. 


We now turn to prove the second part of the lemma. Under the choice ${q}_0 = \frac {d} {d+1}$, we have from \eqref{eq:convert_delta} that
\begin{align*}
    {\Delta}({q}_0) &= \sum\limits_{j=0}^{d-1} \binom{d-1}{j} {q}_0^j (1-{q}_0)^{d-j} (f(j+1) - f(j)) \\
    &\ge {q}_0^{d-1} (1-{q}_0)^{1} (f(d) - f(d-1)) \\ 
    &= \left( 1-\frac{1}{d+1} \right)^d \frac{f(d)-f(d-1)}{d} \\
    &\ge \frac{f(d) - f(d-1)}{ed}. 
\end{align*}
Then, plugging this into \eqref{eq:def:fTp}, we obtain
\begin{align*}
    {\hat{\Gamma}} ({q}_0) = \frac{36.06(1-{q}_0)}{{q}_0 ({\Delta}({q}_0))^2} \log \left( \frac{2n}{\varepsilon} \right) \le \frac{266.45}{(f(d) - f(d-1))^2} d \log \left( \frac{2n}{\varepsilon} \right).
\end{align*}

This completes the proof of Proposition \ref{prop:existence_margin}. 

