    &\le 250678 \times \frac{1}{{\beta}^2} \left( \frac{{U}-{L}}{f({U})-f({L})} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right) \notag\\ 
    &\le { 376017 \times \frac{1}{{\beta}^2} \left( \frac{{U}-{L}}{f({U})-f({L})} \right)^2 d\log \left( \frac{2n}{\varepsilon } \right)}
\end{align}
for some ${q}_0 \in \left(\frac {L} d, \frac {U} d\right)$. 




Case \ref{unify:item2}: For $0 = {L} < {U} \le d-1$, we have ${\beta}=1$ by definition \eqref{eq:def:beta}. 

We proceed with two further sub-cases.
\begin{itemize}
\item \underline{${U}=1$}:  From Proposition \ref{prop:existence_margin} we see that
    \begin{align}
    {\hat{\Gamma}}({q}_0) &\le \frac{266.45}{(f(1)-f(0))^2} d \log \left( \frac{2n}{\varepsilon} \right) \notag\\
    &\le { 376017 \times \frac{1}{{\beta}^2} \left( \frac{{U}-{L}}{f({U})-f({L})} \right)^2 d\log \left( \frac{2n}{\varepsilon } \right)}
    \end{align}
    for ${q}_0=\frac{1}{d+1}\in \left(\frac{{L}}{d},\frac{{U}}{d}\right)$.

\item \underline{${U}\geq 2$}: Both Propositions \ref{prop:existence} and  \ref{prop:existence_margin} are applicable, we prefer to choose the one with smaller upper bound. Applying Proposition \ref{prop:existence} with ${L}'=1$ and ${U}'={U}$, we have that ${{\alpha}}=\frac 1 2$ and 
 \begin{align}
    {\hat{\Gamma}}({q}_0') \le 125339 \times \left( \frac{{U}-1}{f({U})-f(1)} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right)
