    &\le \frac{2{U}^2}{(f({U})-f(0))^2},
\end{align}
it follows that
\begin{align}
    {\hat{\Gamma}} ({q}_0) &\le \min \left\{ 125339 \times \left( \frac{{U}-1}{f({U})-f(1)} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right) , \frac{576.96}{(f(1)-f(0))^2} d \log \left( \frac{2n}{\varepsilon} \right) \right\} \notag\\
    &\le 125339 \times \min \left\{ \frac{1}{(f(1)-f(0))^2} , \frac{({U}-1)^2}{(f({U})-f(1))^2} \right\} \times d\log \left( \frac{2n}{\varepsilon } \right) \notag\\
    &\le 250678 \times \frac{{U}^2}{(f({U})-f(0))^2}  d\log \left( \frac{2n}{\varepsilon } \right) \notag\\
    &= 250678 \times \frac{1}{{\beta}^2} \left( \frac{{U}-{L}}{f({U})-f({L})} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right) \notag\\
