\begin{align}
    &\min \left\{ \frac{1}{(f(1)-f(0))^2} , \frac{1}{(f(d)-f(d-1))^2} ,  \frac{(d-2)^2}{(f(d-1)-f(1))^2} \right\} \notag\\

