for some ${q}_0\in (0,1)$.  Proposition \ref{prop:existence_final} is proved.

The following technical result will serve as a stepping stone to establishing Proposition \ref{prop:existence}. 
\begin{lemma} Let $d\geq 3$. For any ${L}',{U}' \in \{1 ,\dots, d-1\}$ with ${L}' < {U}'$ and $f({L}')<f({U}')$, there exists ${q}_0 \in \left(\frac {{L}'} {d}, \frac {{U}'} {d}\right)$ such that ${\hat{\Gamma}} ({q}_0) $ defined in \eqref{eq:def:fTp} satisfies 
\begin{equation} {\hat{\Gamma}} ({q}_0)  \leq 1253.39 \times \frac{ (d-{L}') {U}' }{{\alpha}^2 (d-{U}'){L}'} \left( \frac{{U}'-{L}'}{f({U}')-f({L}')} \right)^2  d\log \left( \frac{2n}{\varepsilon } \right),
\end{equation} 

where ${\alpha} := \frac{1}{2} \min\left\{{U}'-{L}',\sqrt{{L}'},\sqrt{d-{U}'}\right\}$.
\end{lemma}

\begin{IEEEproof}


See Appendix \ref{proof:lem:existence_pre}.
\end{IEEEproof}
Comparing Proposition \ref{prop:existence} and Lemma \ref{lem:existence_pre}, we see that the main difference is the $\frac{ (d-{L}') {U}' }{(d-{U}'){L}'}$ term. In the remainder of the proof, we manage to eliminate the $\frac{ (d-{L}') {U}' }{(d-{U}'){L}'}$ term from \eqref{eq:existence_pre}. Since ${\alpha} = \frac{1}{2} \min\left\{{U}'-{L}',\sqrt{{L}'},\sqrt{d-{U}'}\right\}$, we consider the following two cases.

Case i): ${\alpha}=\frac {{U}'-{L}'} {2}$, i.e., 
\begin{align}
{U}'-{L}' \leq \min\left\{ \sqrt{{L}'} , \sqrt{d-{U}'} \right\}.
\end{align}
Then we immediately obtain
\begin{equation}
    \frac{(d-{L}'){U}'}{(d-{U}'){L}'} \le \frac{(d-{U}' + \sqrt{d-{U}'})({L}' + \sqrt{{L}'})}{(d-{U}'){L}'}  = \frac{ \sqrt{d-{U}'} +1}{ \sqrt{d-{U}'}}\cdot \frac{\sqrt{{L}'} + 1}{\sqrt{{L}'}}\le 2\times 2 < 25,
\end{equation}
where the second inequality follows from the assumption that $ 1 \le {L}' < {U}' \le d-1$.
Substituting into \eqref{eq:existence_pre}, we have the desired result \eqref{eq:existence_interval_d}. 

Case ii): ${\alpha}\neq \frac {{U}'-{L}'} {2}$, i.e., 
\begin{equation} {\alpha} = \frac{1}{2} \min\left\{ \sqrt{{L}'} , \sqrt{d-{U}'}\right \} < \frac{{U}'-{L}'}{2}. 
\end{equation}
Define 
\begin{align}
{\tau} &:= \left\lfloor \frac{{U}'-{L}'}{\lceil 2{{\alpha}} \rceil} \right\rfloor,\\
{{\lambda}_{{i}}} &:= {L}' + {i}\cdot\lceil 2{{\alpha}} \rceil    \text { for } {i} = 0,\cdots, {\tau}-1, \\
{{\lambda}_{{\tau}}} &:= {U}'.
\end{align}
 For the ease of notation, let 
 \begin{align} {{{\alpha}}_{{i}}} := \frac{1}{2} \min\left\{ {{\lambda}_{{i}+1}}-{{\lambda}_{{i}}} , \sqrt{{{\lambda}_{{i}}}} , \sqrt{d-{{\lambda}_{{i}+1}}}\right \}  \text { for }  {i} = 0,  \cdots , {\tau}-1. 
 \end{align}
The following lemma shows that for all $i=0,\dots, {\tau}-1$, ${{{\alpha}}_{{i}}}$ is bounded from below by ${\alpha}$.
\begin{lemma} ${{{\alpha}}_{{i}}} \ge {{\alpha}}$ for all ${i} \in \{0,\cdots, {\tau}-1\}$. 
\end{lemma}
\begin{IEEEproof}
For ${i} = 0,\cdots, {\tau}-1$, we have from \eqref{eq:def:sigma} that 
\begin{align} {L}' \le {{\lambda}_{{i}}} < {{\lambda}_{{i}+1}} \le {U}'.
\end{align} 
It follows that
\begin{equation} \frac{1}{2} \min\left\{ \sqrt{{{\lambda}_{{i}}}} , \sqrt{d-{{\lambda}_{{i}+1}}} \right\} \ge \frac{1}{2} \min\left\{ \sqrt{{L}'} , \sqrt{d-{U}'}\right \} = {{\alpha}}.
\end{equation}
Next,  for ${i} = 0,\cdots, {\tau}-2$, 
\begin{equation} \frac{{{\lambda}_{{i}+1}}-{{\lambda}_{{i}}}}{2} = \frac{\lceil2{{\alpha}}\rceil}{2} \ge {{\alpha}};
\end{equation}
for ${i} = {\tau}-1$, 
\begin{equation} \frac{{{\lambda}_{{\tau}}}-{{\lambda}_{{\tau}-1}}}{2} = \frac{{U}'-{L}'-({\tau}-1)\lceil2{{\alpha}}\rceil}{2} \ge \frac{{U}'-{L}' - \left( \frac{{U}'-{L}'}{\lceil2{{\alpha}}\rceil}-1 \right) \lceil2{{\alpha}}\rceil}{2} = \frac{\lceil2{{\alpha}}\rceil}{2} \ge {{\alpha}}.
\end{equation}
Combining the above three inequalities, along with the definition of ${{{\alpha}}_{{i}}}$ in \eqref{eq:def:alpha:i}, yields the desired result.
\end{IEEEproof}

To complete the proof of Case ii), the following two lemmas will also be used.
\begin{lemma} $\frac{(d-{{\lambda}_{{i}}}){{\lambda}_{{i}+1}}}{(d-{{\lambda}_{{i}+1}}){{\lambda}_{{i}}}} \le 25$ for any ${i} = 0,\cdots, {\tau}-1$.  
\end{lemma}
\begin{IEEEproof}
Observe that for any $ {i} = 0,\cdots,{\tau}-2$, 
\begin{equation}
    {{\lambda}_{{i}+1}} - {{\lambda}_{{i}}} = \lceil 2{{\alpha}} \rceil \leq 4{{\alpha}}+2;
\end{equation}
and for ${i} = {\tau}-1$, 
\begin{align}
    {{\lambda}_{{\tau}}}-{{\lambda}_{{\tau}-1}} &= {U}' - ({L}'+({\tau}-1)\lceil2{{\alpha}}\rceil) \notag\\ 
    &= {U}' - {L}' - \left( \left\lfloor \frac{{U}'-{L}'}{\lceil2{{\alpha}}\rceil} \right\rfloor - 1 \right) \lceil 2{{\alpha}} \rceil \notag\\ 
    &< {U}' - {L}' - \left( \frac{{U}'-{L}'}{\lceil2{{\alpha}}\rceil} - 2 \right) \lceil 2{{\alpha}} \rceil \notag\\ 
    &= 2 \lceil 2{{\alpha}} \rceil \notag\\ 
    &\leq 4{{\alpha}} + 2.
\end{align}
It then follows that for all $ {i} = 0,\cdots,{\tau}-1$,
\begin{align}
    {{\lambda}_{{i}+1}} - {{\lambda}_{{i}}} &\leq 4{{\alpha}} + 2 \notag\\ 
    &= 2 \min\{\sqrt{{L}'} , \sqrt{d-{U}'}\} + 2 \notag\\ 
    &\le 4 \min\{\sqrt{{L}'} , \sqrt{d-{U}'}\} \notag\\ 
    &\le 4 \min\{\sqrt{{{\lambda}_{{i}}}} , \sqrt{d-{{\lambda}_{{i}+1}}}\},
\end{align}
where the equality follows from \eqref{eq:case2:alpha}; the second inequality follows from the assumption that $ 1 \le {L}' < {U}' \le d-1$; the last inequality follows from \eqref{eq:sigi:lu}.
Using this observation along with $ 1 \leq {{\lambda}_{{i}}}\leq {{\lambda}_{{i}+1}} \leq d-1$, we obtain 
\begin{equation}
    \frac{(d-{{\lambda}_{{i}}}){{\lambda}_{{i}+1}}}{(d-{{\lambda}_{{i}+1}}){{\lambda}_{{i}}}} \leq \frac{(d-{{\lambda}_{{i}+1}}+4\sqrt{d-{{\lambda}_{{i}+1}}}) ({{\lambda}_{{i}}}+4\sqrt{{{\lambda}_{{i}}}})}{(d-{{\lambda}_{{i}+1}}){{\lambda}_{{i}}}}=  \frac{(\sqrt{d-{{\lambda}_{{i}+1}}}+4)}{\sqrt{d-{{\lambda}_{{i}+1}}}}\cdot\frac {(\sqrt{{{\lambda}_{{i}}}}+4)}{\sqrt{{{\lambda}_{{i}}}}}\le 5\times 5=25,
\end{equation}
which finishes the proof.
\end{IEEEproof}


\begin{lemma} $\exists {\ell} \in \{ 0,\cdots,{\tau}-1 \}$ such that $\frac{f({{\lambda}_{{\ell}+1}})-f({{\lambda}_{{\ell}}})}{{{\lambda}_{{\ell}+1}}-{{\lambda}_{{\ell}}}} \ge \frac{f({U}')-f({L}')}{{U}'-{L}'}$. 
