The proof of Lemma \ref{lem:cv_H} will resort to the following technical lemma:
\begin{lemma} For any $ {b} \in (0,1)$ and ${c} \in (-{b},1-{b})$, it follows that 
\begin{equation*}
    -{b} \ln{b} + ({b}+{c})\ln({b}+{c}) \le {c} (1+ \ln {b} ) + \frac{{c}^2}{{b}}.
\end{equation*}
\end{lemma}
\begin{IEEEproof}
Since ${b} + {c} > 0$, $\frac{{c}}{{b}} > -1$, we have 
\begin{align*}
    0 &\le ({b}+{c}) \left( \frac{{c}}{{b}} - \ln\left( 1 + \frac{{c}}{{b}} \right) \right) \\ 
    &= {c} + \frac{{c}^2}{{b}} - ({b}+{c})\ln({b}+{c}) + ({b}+{c})\ln{b},
\end{align*}
which, via simple rearrangement, gives the promised inequality.
\end{IEEEproof}

We now set out to prove Lemma \ref{lem:cv_H}. First, we have
\begin{align} {H}({Y}_i) - {H}({Y}_i|{Z}_i)&= {H}({Y}_i) - \sum\limits_{{a}=0}^{d} \Pr({Z}_i={a}) {H}({Y}_i | {Z}_i={a}) \notag\\
    &= \sum\limits_{{a}=0}^{d} \Pr({Z}_i={a}) \left[{H}({Y}_i) - {H}({Y}_i | {Z}_i={a})\right]
\end{align}
For the sake of notational brevity, let ${\mu}={\mu}({\chi}_i)$ and ${\sigma^{2}}={\sigma^{2}}({\chi}_i)$. Since 
\begin{align*}
\Pr ({Y}_i = 1|{Z}_i={a}) =f(a),
\end{align*}
\begin{align*}
\Pr ({Y}_i = 1)=\sum\limits_{{a}=0}^{d} \Pr({Z}_i={a})\Pr ({Y}_i = 1|{Z}_i={a}) =\sum\limits_{{a}=0}^{d} \Pr({Z}_i={a})f(a)={\mu},
\end{align*}
we have
\begin{align} \begin{aligned}
     {H}({Y}_i) &= -{\mu} \log {\mu} - (1-{\mu}) \log (1-{\mu}) \\
                 &=\left[-{\mu} \ln {\mu} - (1-{\mu}) \ln (1-{\mu})\right]\log e, \\
     {H}({Y}_i | {Z}_i={a}) &= - f({a}) \log f({a}) - (1-f({a})) \log (1-f({a}))\\
     &= \left[- f({a}) \ln f({a}) - (1-f({a})) \ln (1-f({a}))\right]\log e.
\end{aligned}
\end{align}
Next, we argue that 
\begin{align} \kern-.5em     -{\mu} \ln {\mu} - (1-{\mu}) \ln (1-{\mu}) + f({a}) \ln f({a}) + (1-f({a})) \ln (1-f({a})) 
    &\leq (f({a})-{\mu}) (\ln {\mu} - \ln(1-{\mu})) + \frac{(f({a})-{\mu})^2}{{\mu}(1-{\mu})}.
\end{align}
This is done for each of the following possible cases.
\begin{itemize}
\item When $f({a})=0$, 
\begin{equation*}
    {\text{L.H.S.}} - {\text{R.H.S.}} = 1 - \frac{1}{1-{\mu}} - \ln(1-{\mu}) \le 0,\quad \forall\, 0 < {\mu}< 1.
\end{equation*}
\item When $f({a})=1$, 
\begin{equation*}
    {\text{L.H.S.}} - {\text{R.H.S.}} = 1 - \frac{1}{{\mu}} - \ln{\mu} \le 0,\quad \forall\, 0< {\mu}< 1.
\end{equation*}
\item When $f({a}) \in (0,1)$, applying Lemma \ref{lem:cv:series} with ${b}={\mu}$ and ${c} = f({a})-{\mu}$ we obtain  
\begin{equation*}
    -{\mu} \ln {\mu} + f({a}) \ln f({a}) \le (f({a})-{\mu}) (1+\ln{\mu} ) + \frac{(f({a})-{\mu})^2}{{\mu}}.
\end{equation*}
Applying Lemma \ref{lem:cv:series} again with ${b}=1-{\mu}$ and ${c}={\mu}-f({a})$, we obtain  
\begin{equation*}
    -(1-{\mu}) \ln (1-{\mu}) + (1-f({a})) \ln (1-f({a})) \leq ({\mu}-f({a})) (1+\ln(1-{\mu})) + \frac{(f({a})-{\mu})^2}{1-{\mu}}. 
\end{equation*}
