\begin{equation} {{P}({\hat{d}},{\zeta})} = \sum\limits_{j=0}^{{\hat{d}}} \binom{{\hat{d}}}{j} {\zeta}^j (1-{\zeta})^{{\hat{d}}-j} f(j).
\end{equation}
