    \State Take ${t({\hat{d}},{\zeta},{\epsilon})}$ tests of the Bernoulli test design with parameter ${\zeta}$, where
     \begin{equation} {t({\hat{d}},{\zeta},{\epsilon})} := \left\lceil 8.32 \left( \frac{1-{\zeta}}{{\zeta} {\Delta({\hat{d}},{\zeta})}} \right)^2 \log \frac{1}{{\epsilon}} \right\rceil. 
     \end{equation}
    \State Let ${t^{+}({\hat{d}},{\zeta},{\epsilon})}$ denote the number of tests with positive outcome within these ${t({\hat{d}},{\zeta},{\epsilon})}$ tests. If
    \begin{equation} \frac{{t^{+}({\hat{d}},{\zeta},{\epsilon})}}{{t({\hat{d}},{\zeta},{\epsilon})}} \le {{P}({\hat{d}},{\zeta})} - \frac{{\zeta}}{2(1-{\zeta})} {\Delta({\hat{d}},{\zeta})},
    \end{equation}
    return  $d \le {\hat{d}}-1$; otherwise, return $d \ge {\hat{d}}$.
    \end{algorithmic}
\end{algorithm}
